    },
    {
      "recordId": "SYN-PUB-10523",
      "field": "abstract",
      "quote": "This paper presents an unsupervised anomaly detection framework specifically designed for Modbus traffic analysis. The proposed approach leverages autoencoder-based neural networks trained exclusively on benign traffic to establish a baseline behavioural profile of legitimate industrial communications. Anomalies are identified by measuring reconstruction error against learned normal patterns, without requiring labelled attack data."
    },
    {
      "recordId": "R1015",
      "field": "open_to",
      "quote": "industrial PhD supervision; joint projects"
    }
  ],
  "plan": {
    "question": "Can an autoencoder-based reconstruction error model trained exclusively on benign Modbus traffic archives from a specific site reliably flag behavioral drift without generating excessive false positives? If the pilot succeeds, a conditional industrial PhD research question could investigate lightweight multi-protocol autoencoder architectures optimized for edge hardware operating on both Modbus and BACnet networks.",
    "experiment": "Propose evaluating an unsupervised autoencoder network on a subset of the company's multi-terabyte benign Modbus traffic archives, using historical benign captures for training and held-out benign operational windows for baseline false-positive measurement.",
    "metrics": "Measure baseline false positive rate per operational day and reconstruction error distribution variance on unseen benign traffic windows.",
    "companyAsk": "Provide access to historical Modbus traffic archives, the hardware testbench, and part-time allocation of one to two engineers under NDA.",
    "researcherAsk": "Contribute academic advisory input on autoencoder architecture configuration, window size selection, and anomaly threshold tuning.",
    "milestones": "Weeks 1-2: Environment setup and data sanitisation; Weeks 3-4: Baseline autoencoder training on benign Modbus captures; Weeks 5-6: False-positive evaluation and threshold calibration; Week 8: Final pilot review deliverable.",
    "risks": "Potential risks include high false positive rates due to unmodelled benign operational bursts, and edge hardware inference latency constraints.",
    "meeting": "Week 1 kickoff agenda: review NDA status, inspect sample anonymous Modbus packet captures, agree on evaluation metrics, and assign data preprocessing tasks.",
    "terms": "Discuss negotiable research collaboration terms, background IP protection, publication rights for joint findings, and potential subsequent industrial PhD frameworks."
  }
}

